document.addEventListener("DOMContentLoaded",function(){const navLinks=document.querySelectorAll(".nav-link");navLinks.forEach(link=>{link.addEventListener("click",function(e){e.preventDefault();const targetId=this.getAttribute("href").substring(1);const targetSection=document.getElementById(targetId);if(targetSection){const headerHeight=document.querySelector(".header").offsetHeight;const targetPosition=targetSection.offsetTop-headerHeight;window.scrollTo({top:targetPosition,behavior:"smooth"})}})});window.addEventListener("scroll",function(){const sections=document.querySelectorAll("section[id]");const scrollPosition=window.scrollY+document.querySelector(".header").offsetHeight+50;sections.forEach(section=>{const sectionTop=section.offsetTop;const sectionHeight=section.offsetHeight;const sectionId=section.getAttribute("id");if(scrollPosition>=sectionTop&&scrollPosition<sectionTop+sectionHeight){navLinks.forEach(link=>link.classList.remove("active"));const activeLink=document.querySelector(`.nav-link[href="#${sectionId}"]`);if(activeLink){activeLink.classList.add("active")}}})});const observerOptions={threshold:.1,rootMargin:"0px 0px -50px 0px"};const observer=new IntersectionObserver(function(entries){entries.forEach(entry=>{if(entry.isIntersecting){entry.target.style.opacity="1";entry.target.style.transform="translateY(0)"}})},observerOptions);const featureCards=document.querySelectorAll(".feature-card");featureCards.forEach(card=>{card.style.opacity="0";card.style.transform="translateY(30px)";card.style.transition="opacity 0.6s ease, transform 0.6s ease";observer.observe(card)});const createMobileMenu=()=>{const navbar=document.querySelector(".navbar");const navContainer=document.querySelector(".nav-container");const mobileMenuButton=document.createElement("button");mobileMenuButton.className="mobile-menu-button";mobileMenuButton.innerHTML="☰";mobileMenuButton.style.display="none";mobileMenuButton.style.background="none";mobileMenuButton.style.border="none";mobileMenuButton.style.fontSize="1.5rem";mobileMenuButton.style.cursor="pointer";mobileMenuButton.style.color="#1a4d2e";const navMenu=document.querySelector(".nav-menu");navContainer.insertBefore(mobileMenuButton,navMenu);mobileMenuButton.addEventListener("click",function(){navMenu.classList.toggle("mobile-menu-open")});function checkScreenSize(){if(window.innerWidth<=768){mobileMenuButton.style.display="block";navMenu.style.display=navMenu.classList.contains("mobile-menu-open")?"flex":"none"}else{mobileMenuButton.style.display="none";navMenu.style.display="flex";navMenu.classList.remove("mobile-menu-open")}}checkScreenSize();window.addEventListener("resize",checkScreenSize)};createMobileMenu();initializeLightbox();document.body.style.opacity="0";document.body.style.transition="opacity 0.5s ease";window.addEventListener("load",function(){document.body.style.opacity="1"});const emailLink=document.querySelector('a[href^="mailto:"]');if(emailLink){emailLink.addEventListener("click",function(){console.log("Email contact initiated")})}});function initializeLightbox(){const lightbox=document.getElementById("lightbox");if(!lightbox){console.warn("Lightbox element not found");return}const lightboxImage=lightbox.querySelector(".lightbox-image");const lightboxCaption=lightbox.querySelector(".lightbox-caption");const closeBtn=lightbox.querySelector(".lightbox-close");const prevBtn=lightbox.querySelector(".lightbox-prev");const nextBtn=lightbox.querySelector(".lightbox-next");if(!lightboxImage||!lightboxCaption||!closeBtn||!prevBtn||!nextBtn){console.warn("Required lightbox elements not found");return}let currentImageIndex=0;let currentImageSet=[];const clickableImages=document.querySelectorAll(".gallery-item img, .feature-image, .location-image");clickableImages.forEach((img,index)=>{img.classList.add("clickable-image");img.addEventListener("click",()=>openLightbox(img,index))});let keydownHandler=null;function addKeyboardListener(){if(keydownHandler)return;keydownHandler=e=>{if(!lightbox.classList.contains("active"))return;switch(e.key){case"Escape":closeLightbox();break;case"ArrowLeft":if(currentImageSet.length>1)showPrevImage();break;case"ArrowRight":if(currentImageSet.length>1)showNextImage();break}};document.addEventListener("keydown",keydownHandler)}function removeKeyboardListener(){if(keydownHandler){document.removeEventListener("keydown",keydownHandler);keydownHandler=null}}function openLightbox(clickedImage,index){if(clickedImage.closest(".gallery-item")){currentImageSet=document.querySelectorAll(".gallery-item img");currentImageIndex=Array.from(currentImageSet).indexOf(clickedImage)}else if(clickedImage.classList.contains("feature-image")){currentImageSet=document.querySelectorAll(".feature-image");currentImageIndex=Array.from(currentImageSet).indexOf(clickedImage)}else if(clickedImage.classList.contains("location-image")){currentImageSet=document.querySelectorAll(".location-image");currentImageIndex=Array.from(currentImageSet).indexOf(clickedImage)}else{currentImageSet=[clickedImage];currentImageIndex=0}updateLightboxImage();lightbox.classList.add("active");lightbox.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";addKeyboardListener();closeBtn.focus()}function closeLightbox(){lightbox.classList.remove("active");lightbox.setAttribute("aria-hidden","true");document.body.style.overflow="";removeKeyboardListener()}function updateLightboxImage(){const currentImage=currentImageSet[currentImageIndex];lightboxImage.src=currentImage.src;lightboxImage.alt=currentImage.alt;let captionText="";if(currentImage.closest(".gallery-item")){const captionElement=currentImage.closest(".gallery-item").querySelector(".gallery-caption");captionText=captionElement?captionElement.textContent:currentImage.alt}else if(currentImage.closest(".feature-card")){const titleElement=currentImage.closest(".feature-card").querySelector("h3");captionText=titleElement?titleElement.textContent:currentImage.alt}else{captionText=currentImage.alt}lightboxCaption.textContent=captionText;if(currentImageSet.length>1){prevBtn.style.display="flex";nextBtn.style.display="flex"}else{prevBtn.style.display="none";nextBtn.style.display="none"}}function showPrevImage(){currentImageIndex=(currentImageIndex-1+currentImageSet.length)%currentImageSet.length;updateLightboxImage()}function showNextImage(){currentImageIndex=(currentImageIndex+1)%currentImageSet.length;updateLightboxImage()}closeBtn.addEventListener("click",closeLightbox);prevBtn.addEventListener("click",showPrevImage);nextBtn.addEventListener("click",showNextImage);lightbox.addEventListener("click",e=>{if(e.target===lightbox){closeLightbox()}})}const mobileMenuStyles=`\n    @media (max-width: 768px) {\n        .nav-menu {\n            position: absolute;\n            top: 100%;\n            left: 0;\n            width: 100%;\n            background: rgba(255, 255, 255, 0.98);\n            backdrop-filter: blur(10px);\n            flex-direction: column;\n            padding: 1rem 0;\n            border-top: 1px solid rgba(0, 0, 0, 0.1);\n            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\n        }\n        \n        .nav-menu.mobile-menu-open {\n            display: flex !important;\n        }\n        \n        .nav-link.active {\n            color: #1a4d2e;\n            font-weight: 600;\n        }\n    }\n`;const styleSheet=document.createElement("style");styleSheet.textContent=mobileMenuStyles;document.head.appendChild(styleSheet);